#!/usr/bin/env python3
# -*- coding: utf-8 -*-
import json, html, re

Q = json.load(open('/home/dp/MyProjects/disc/.tmpwork/disc-pi-ubh5lmsd/run/Q.json', encoding='utf-8'))
assert len(Q) == 24 and all(len(x) == 4 for x in Q)
TITLES = ["Первый", "Второй", "Третий", "Четвертый", "Пятый", "Шестой", "Седьмой", "Восьмой"]

HANDLE = '''<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden="true"><path d="M5 4C5 3.86 5 3.791 5.008 3.733C5.03345 3.54971 5.11803 3.37973 5.24888 3.24888C5.37973 3.11803 5.54971 3.03345 5.733 3.008C5.79 3 5.86 3 6 3C6.14 3 6.209 3 6.267 3.008C6.45029 3.03345 6.62027 3.11803 6.75112 3.24888C6.88197 3.37973 6.96655 3.54971 6.992 3.733C7 3.79 7 3.86 7 4C7 4.14 7 4.209 6.992 4.267C6.96655 4.45029 6.88197 4.62027 6.75112 4.75112C6.62027 4.88197 6.45029 4.96655 6.267 4.992C6.21 5 6.14 5 6 5C5.86 5 5.791 5 5.733 4.992C5.54904 4.96655 5.37939 4.88197 5.24888 4.75112C5.11803 4.62027 5.03345 4.45029 5.008 4.267C5 4.21 5 4.14 5 4ZM5 8C5 7.86 5 7.791 5.008 7.733C.03345 7.54971 5.11803 7.37973 5.24888 7.24888C5.37973 7.11803 5.54971 7.03345 5.733 7.008C5.79 7 5.86 7 6 7C6.14 7 6.209 7 6.267 7.008C6.45029 7.03345 6.62027 7.11803 6.75112 7.24888C6.88197 7.37973 6.96655 7.54971 6.992 7.733C7 7.79 7 7.86 7 8C7 8.14 7 8.209 6.992 8.267C6.96655 8.45029 6.88197 8.62027 6.75112 8.75112C6.62027 8.88197 6.45029 8.96655 6.267 8.992C6.21 9 6.14 9 6 9C5.86 9 5.791 9 5.733 8.992C5.54904 8.96655 5.37939 8.88197 5.24888 8.75112C5.11812 8.62027 5.0336 8.45 5.008 8.267C5 8.21 5 8.14 5 8Z" fill="#B3B3B3"/></svg>'''

def card_html(i, j):
    items = ''
    for k in range(4):
        t, a = Q[i][k]
        items += f'<li data-type="{t}" id="item-{i}-{k}" class="row"><span class="handle">{HANDLE}</span><span class="txt">{html.escape(a)}</span></li>'
    return (
        f'<div class="card"><div class="card__title">Я наиболее</div>'
        f'<ul class="dlist" id="list-{i}-{j}">' + items + '</ul>'
        f'<div class="card__foot">Я наименее</div></div>'
    )

dots = ''.join(f'<div class="dot" data-step="{s}">{s+1}</div>' for s in range(8))
cards = ''.join(card_html(i, j) for i in range(24) for j in range(3))

CSS = """
  :root{
    --bg:#0e1023;--card:#191b36;--card2:#1f2243;--line:#2a2e54;
    --txt:#eef1ff;--muted:#a7adca;--accent:#6472ff;--accent2:#0fd0c2;
    --d:#ff5f6d;--i:#ffb347;--s:#7bd88f;--c:#6fa8ff;
  }
  *{box-sizing:border-box}
  html,body{margin:0;padding:0}
  body{
    font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
    background:var(--bg);color:var(--txt);min-height:100vh;line-height:1.55;
    -webkit-font-smoothing:antialiased;
  }
  .wrap{max-width:960px;margin:0 auto;padding:34px 20px 70px}
  h1{font-size:clamp(26px,4vw,46px);font-weight:800;margin:12px 0 6px;letter-spacing:-.6px;text-align:center}
  .lead{text-align:center;color:var(--muted);max-width:620px;margin:0 auto 8px;font-size:17px}
  .btn{
    cursor:pointer;border:none;border-radius:12px;padding:14px 26px;font-size:17px;font-weight:650;
    background:linear-gradient(135deg,var(--accent),var(--accent2));color:#fff;user-select:none;
    transition:transform .12s,opacity .2s,box-shadow .2s;box-shadow:0 6px 20px rgba(100,114,255,.25);
  }
  .btn:hover{transform:translateY(-1px)}
  .btn:active{transform:translateY(0)}
  .btn.ghost{background:var(--card2);color:var(--txt);box-shadow:none;border:1px solid var(--line)}
  .btn:disabled{opacity:.35;cursor:not-allowed;transform:none;box-shadow:none}
  .center{text-align:center;margin-top:30px}
  .sub{text-align:center;color:var(--muted);margin:2px 0 6px}
  .stepcount{color:var(--txt);text-align:center;font-weight:700;letter-spacing:.4px;margin-top:16px}
  .steps{display:flex;flex-wrap:wrap;gap:7px;justify-content:center;margin:26px 0 4px}
  .dot{
    width:40px;height:40px;border-radius:50%;display:flex;align-items:center;justify-content:center;
    font-size:14px;font-weight:700;background:var(--card);color:var(--muted);border:1px solid var(--line);
    transition:.2s;
  }
  .dot.active{background:var(--accent);color:#fff;border-color:var(--accent)}
  .dot.done{background:var(--accent2);color:#06131a;border-color:var(--accent2)}
  .progress{height:8px;background:var(--card);border-radius:7px;overflow:hidden;margin-bottom:26px}
