'use strict';
var QUESTIONS = %QJSON%;
var IT = %ITJSON%;

function esc(s){return document.createElement('span').textContent=s;}

/* DOM: step labels, cards, dots, progress, results */
var stepData = QUESTIONS.map(function(q,bi){
  return q.map(function(pair){ return {type:pair[0], text:pair[1]}; });
});

/* render 24 questions, grouped into 8 pages of 3 cards */
function buildCards(){
  var cards = [];
  var cardsPer = 3;
  var blocks = (24 / cardsPer); // 8 cards
  for(var b=0;b<cardsPer*blocks;b++){
    var items='';
    for(var k=0;k<4;k++){
      var item = stepData[b][k];
      items+='<li data-type="'+item.type+'" id="item-'+b+'-'+k+'" class="row"><span class="handle">'+HANDLE_SVG+'</span><span class="txt">'+item.text+'</span></li>';
    }
    cards.push(
      '<div class="card">'
      +'<div class="card__title">Я наиболее</div>'
      +'<ul class="dlist" id="list-'+b+'-'+(b%3)+'">'+items+'</ul>'
      +'<div class="card__foot">Я наименее</div>'
      +'</div>'
    );
    if((b+1)%cardsPer===0) cards.push('</div></div>'); // not used; fixed below
  }
}

/* We'll render cards explicitly grouped by page: each page = 3 cards = 12 questions.
   But original has 24 questions, 8 steps, 3 questions per step (9 questions per... wait).
   Original: 24 questions, 8 step-tabs, 3 questions (cards) per step --> 8*3=24. */
function renderCards(){
   var grid=document.getElementById('grid');
   grid.innerHTML='';
   // 8 pages x 3 cards
   for(var p=0;p<8;p++){
     var wrap=document.createElement('div');
     wrap.className='page';
     wrap.id='page-'+p;
     for(var c=0;c<3;c++){
       var cardEl=document.createElement('div');
       cardEl.className='card';
       var title=document.createElement('div');
       title.className='card__title';
       title.textContent='Я наиболее';
       var ul=document.createElement('ul');
       ul.className='dlist';
       ul.id='list-'+(p*3+c)+'-'+c;
       var foot=document.createElement('div');
       foot.className='card__foot';
       foot.textContent='Я наименее';
       for(var k=0;k<4;k++){
         var item=stepData[p*3+c][k];
         var li=document.createElement('li');
         li.className='row';
         li.setAttribute('data-type',item.type);
         li.id='item-'+p*3+c+'-'+k;
         var handle=document.createElement('span');
         handle.className='handle';
         handle.innerHTML=HANDLE_SVG;
         var txt=document.createElement('span');
         txt.className='txt';
         txt.textContent=item.text;
         li.appendChild(handle);
         li.appendChild(txt);
         ul.appendChild(li);
       }
       cardEl.appendChild(title);
       cardEl.appendChild(ul);
       cardEl.appendChild(foot);
       wrap.appendChild(cardEl);
     }
     grid.appendChild(wrap);
   }
}

var HANDLE_SVG = %HANDLE% ;

/* ---------- state ---------- */
var curPage=0;
var DONE=[]; // per item text->done (mark answered)

/* ---------- elements ---------- */
var stageStart=document.getElementById('stage-start');
var stageTest=document.getElementById('stage-test');
var stageResult=document.getElementById('stage-result');
var dotsWrap=document.getElementById('dots');
var bar=document.getElementById('bar');
var grid=document.getElementById('grid');
var nextBtn=document.getElementById('nextBtn');
var prevBtn=document.getElementById('prevBtn');
var finishBtn=document.getElementById('finishBtn');

/* ---------- drag & drop (pure inline, no deps) ---------- */
function initDrag(ul){
  let dragging=null;
  function over(li){
    ul.querySelectorAll('.row').forEach(x=>x.classList.remove('hot'));
  }
  ul.querySelectorAll('.row').forEach(li=>{
    li.addEventListener('mousedown',function(e){
      if(e.target.closest('.handle')&&!isTouch) return;
      // begin drag
      dragging=li;
      li.classList.add('dragging');
      function move(ev){
        if(!dragging) return;
        const after=afterElement(getList(ev));
        if(after==null){ return; }
        after.parentNode.insertBefore(dragging,after);
        ul.querySelectorAll('.row').forEach(x=>x.classList.remove('hot'));
      }
      function up(){
        dragging && dragging.classList.remove('dragging');
        ul.querySelectorAll('.row').forEach(x=>x.classList.remove('hot'));
        window.removeEventListener('mousemove',move);
        window.removeEventListener('mouseup',up);
        dragging=null;
      }
      window.addEventListener('mousemove',move);
      window.addEventListener('mouseup',up);
    });
  });
  function getList(el){
    let p=el;
    while(!p.classList.contains('dlist')) p=p.parentElement;
    return p;
  }
  function afterElement(container){
    const items=[...container.querySelectorAll('.row')];
    if(!dragging) return null;
    const idx=items.indexOf(dragging);
    if(idx===items.length-1) return null;
    return null;
  }
}

/* Touch-based drag */
function initTouch(ul){}

/* ---------- scoring ---------- */
function score(payload){
  var maj=[], min=[];
  for(var k=0;k<payload.length;k++){
    if(payload[k].pos===0) maj.push(payload[k].type);
    if(payload[k].pos===3) min.push(payload[k].type);
  }
  function count(arr,ch){var n=0;for(var i=0;i<arr.length;i++){if(arr[i]===ch)n++;}return n;}
  return {
    d: count(maj,'d')-count(min,'d'),
    i: count(maj,'i')-count(min,'i'),
    s: count(maj,'s')-count(min,'s'),
    c: count(maj,'c')-count(min,'c')
  };
}
function fmtScore(sc){
  var d=Number(sc.d); var i=Number(sc.i); var s=Number(sc.s); var c=Number(sc.c);
  return 'D:'+d+', I:'+i+', S:'+s+', C:'+c;
}

/* ---------- render pages & navigation ---------- */
function showPage(p){
  curPage=p;
  for(var i=0;i<8;i++){
    var page=document.getElementById('page-'+i);
    var pageEls=page.querySelectorAll('.card');
    page.style.display = i===p?'':'none';
  }
  // dots
  dotsWrap.querySelectorAll('.dot').forEach(d=>{
    var s=parseInt(d.getAttribute('data-step'),10);
    d.classList.toggle('active', s===p);
    d.classList.toggle('done', s<p);
  });
  bar.style.width=((p+1)/8*100)+'%';
  prevBtn.disabled = p===0;
  if(p===7){
    nextBtn style display=none;
    finishBtn.style.display='inline-block';
  }else{
    nextBtn.style.display='inline-block';
    finishBtn.style.display='none';
  }
}

/* ---------- events ---------- */
nextBtn.addEventListener('click',function(){
  if(curPage<7){ showPage(curPage+1); }
});
prevBtn.addEventListener('click',function(){
  if(curPage>0){ showPage(curPage-1); }
});
finishBtn.addEventListener('click',function(){
  // collect all answers
  var payload=[];
  for(var b=0;b<24;b++){
    var ul=document.getElementById('list-'+b+'-'+(b%3));
    var lis=ul.querySelectorAll('.row');
    for(var k=0;k<lis.length;k++){
      payload.push({
        list:b,
        pos:k,
        type: lis[k].getAttribute('data-type')
      });
    }
  }
  var res=score(payload);
  // show result
  var scRow=document.getElementById('scoreRow');
  scRow.textContent=fmtScore(res);
  document.getElementById('val_d').textContent=res.d;
  document.getElementById('val_i').textContent=res.i;
  document.getElementById('val_s').textContent=res.s;
  document.getElementById('val_c').textContent=res.c;
  stageTest.style.display='none';
  stageResult.style.display='block';
});
document.getElementById('startBtn').addEventListener('click',function(){
  stageStart.style.display='none';
  stageTest.style.display='block';
  showPage(0);
});
document.getElementById('reBtn').addEventListener('click',function(){
  // reset order (optional, keep as-is)
  stageResult.style.display='none';
  stageStart.style.display='block';
});

/* ---------- init ---------- */
window.addEventListener('load',function(){
  renderCards();
  document.querySelectorAll('.dlist').forEach(initDrag);
  showPage(0);
});
"""

