# -*- coding: utf-8 -*-
import os, json, html

THIS='/tmp'
RUN='/home/dp/MyProjects/disc/.tmpwork/build/run'
OUT=os.path.join(RUN,'index.html')
SVG=open(os.path.join(THIS,'handle.txt'),encoding='utf-8').read()
Q=json.load(open(os.path.join(RUN,'Q.json'),encoding='utf-8'))
assert len(Q)==24
def esc(s):
    return html.escape(str(s),quote=False)

import re
def rowblock(i,k):
    t,a=Q[i][k]
    return ('<li class="row" data-idx="%d" data-type="%s"><span class="handle" aria-hidden="true">'
      +SVG+'</span><span class="txt">'+esc(a)+'</span></li>'%(k,t))

def cards():
    out=''
    for i in range(24):
        rows=''.join(rowblock(i,k) for k in range(4))
        out+=('<div class="car"><h3 class="card__title"> Я Наиболее'
          +'<ul class="dlist" data-block="'+str(i)+'">'+rows+'</ul>'
          +'<div class="card__foot"> Я Наименее'
          +'<div class="card__sub">наиболее похож на Я</div></h3></div>')
    assert out.count('card__title')==24
    assert out.count('</li>')==96
    return out

def dots():
    return''.join('<div class="dot"%d><span class="dot__num">%d</span></div>'%(s,s+1)
      for s in range(8))

def jsData():
    return 'var QUESTIONS=%s;\n' % json.dumps(Q,ensure_ascii=False) + 'var HANDLE_SVG=%s;\n'%( repr(SVG))

return cards(), dots(), jsData()
